"""Pure Markdown to Telegram HTML conversion and length-safe splitting. Nothing here performs IO; TelegramBot owns delivery."""

def escape_html(text: str) -> str:
    """HTML-escape ampersand, less-than and greater-than so user text can never inject a tag. Runs first; every later step appends tags after this point, so generated tags are never re-escaped."""
    amp: str = regex_replace("&", "&amp;", text)
    lt: str = regex_replace("<", "&lt;", amp)
    return regex_replace(">", "&gt;", lt)

def apply_inline(s: str) -> str:
    """Apply inline Markdown to an already-escaped segment that is not inside a code span. Longest delimiters first - double asterisk before single, double underscore before single - so bold never degrades into italics. Emits only Telegram-allowed tags."""
    links: str = regex_replace(r"\[([^\]]+)\]\(([^)]+)\)", '<a href="$2">$1</a>', s)
    spoiler: str = regex_replace(r"\|\|(.+?)\|\|", "<tg-spoiler>$1</tg-spoiler>", links)
    strike: str = regex_replace("~~(.+?)~~", "<s>$1</s>", spoiler)
    bold1: str = regex_replace(r"\*\*(.+?)\*\*", "<b>$1</b>", strike)
    bold2: str = regex_replace("__(.+?)__", "<b>$1</b>", bold1)
    ital1: str = regex_replace(r"\*(.+?)\*", "<i>$1</i>", bold2)
    return regex_replace("_(.+?)_", "<i>$1</i>", ital1)

def tag(name: str, closing: bool) -> str:
    """Build an HTML tag from separate pieces. The source never contains a literal closing code or pre tag, because the runtime stops reading this code block at the first closing code fence it sees anywhere in the payload - including inside a string."""
    if closing:
        return concat("</", name, ">")
    return concat("<", name, ">")

def code_wrap(s: str) -> str:
    """Wrap text in a code tag. Tests use this to build expected values the source cannot write literally."""
    return concat(TgFormat.tag("code", False), s, TgFormat.tag("code", True))

def code_segments(parts: list[str], i: int, acc: str) -> str:
    """Fold the backtick-split segments of a single line: even segments are prose with Markdown applied, odd segments are code spans wrapped in a code tag with every other rule skipped."""
    if i >= len(parts):
        return acc
    seg: str = get(parts, i)
    if rem(i, 2) == 0:
        return TgFormat.code_segments(parts, i + 1, concat(acc, TgFormat.apply_inline(seg)))
    else:
        return TgFormat.code_segments(parts, i + 1, concat(acc, TgFormat.code_wrap(seg)))

def inline_code(s: str) -> str:
    """Convert one line of inline Markdown while protecting backtick code spans from the other rules."""
    return TgFormat.code_segments(split(s, "`"), 0, "")

def convert_line(line: str) -> str:
    """Convert one non-fence line: heading, blockquote, bullet or plain prose. The blockquote marker is matched in its ESCAPED form, because escaping runs first by design - the source line starts with the gt entity, not a bare angle bracket."""
    t: str = trim(line)
    if starts_with(t, "### "):
        return concat("<b>", TgFormat.inline_code(substring(t, 4, len(t))), "</b>")
    if starts_with(t, "## "):
        return concat("<b>", TgFormat.inline_code(substring(t, 3, len(t))), "</b>")
    if starts_with(t, "# "):
        return concat("<b>", TgFormat.inline_code(substring(t, 2, len(t))), "</b>")
    if starts_with(t, "&gt; "):
        return concat("<blockquote>", TgFormat.inline_code(substring(t, 5, len(t))), "</blockquote>")
    if t == "&gt;":
        return "<blockquote></blockquote>"
    if starts_with(t, "- "):
        return concat("• ", TgFormat.inline_code(substring(t, 2, len(t))))
    if starts_with(t, "* "):
        return concat("• ", TgFormat.inline_code(substring(t, 2, len(t))))
    return TgFormat.inline_code(line)

def convert_lines(lines: list[str], i: int, in_pre: bool, buf: str, acc: list[str]) -> list[str]:
    """Walk the escaped lines, folding each fenced block into ONE pre-tagged element so no later step can split it apart or reformat its contents."""
    if i >= len(lines):
        if in_pre:
            return push(acc, concat(TgFormat.tag("pre", False), buf, TgFormat.tag("pre", True)))
        return acc
    raw: str = get(lines, i)
    if starts_with(trim(raw), "```"):
        if in_pre:
            return TgFormat.convert_lines(lines, i + 1, False, "", push(acc, concat(TgFormat.tag("pre", False), buf, TgFormat.tag("pre", True))))
        return TgFormat.convert_lines(lines, i + 1, True, "", acc)
    if in_pre:
        if buf == "":
            return TgFormat.convert_lines(lines, i + 1, True, raw, acc)
        return TgFormat.convert_lines(lines, i + 1, True, concat(buf, "\n", raw), acc)
    return TgFormat.convert_lines(lines, i + 1, False, "", push(acc, TgFormat.convert_line(raw)))

def markdown_to_html(text: str) -> str:
    """Markdown to Telegram HTML. Escapes first, so user text can never inject a tag; every tag added afterwards is generated by this module."""
    esc: str = TgFormat.escape_html(text)
    lines: list[str] = split(esc, "\n")
    parts: list[str] = TgFormat.convert_lines(lines, 0, False, "", [])
    return join(parts, "\n")

def pre_wrap(s: str) -> str:
    """Wrap text in a pre tag. Tests and samples build expected values through this because the source cannot contain a literal closing pre tag."""
    return concat(TgFormat.tag("pre", False), s, TgFormat.tag("pre", True))

def split_parts(lines: list[str], i: int, part: str, depth: int, limit: int, acc: list[str]) -> list[str]:
    """Fold lines into parts; a break only when it starts and ends outside a pre block."""
    if i >= len(lines):
        if part == "":
            return acc
        return push(acc, part)
    line: str = get(lines, i)
    opens: int = len(split(line, TgFormat.tag("pre", False))) - 1
    closes: int = len(split(line, TgFormat.tag("pre", True))) - 1
    ndepth: int = depth + opens - closes
    if part == "":
        return TgFormat.split_parts(lines, i + 1, line, ndepth, limit, acc)
    if depth == 0 and ndepth == 0 and len(concat(part, "\n", line)) > limit:
        return TgFormat.split_parts(lines, i + 1, line, ndepth, limit, push(acc, part))
    return TgFormat.split_parts(lines, i + 1, concat(part, "\n", line), ndepth, limit, acc)

def split_for_telegram(html: str, limit: int) -> list[str]:
    """Split converted HTML into message-sized parts on line boundaries. Telegram rejects text over 4096 characters, so callers pass a limit comfortably below that."""
    return TgFormat.split_parts(split(html, "\n"), 0, "", 0, limit, [])

def parts_preview(html: str, limit: int) -> str:
    """Render split parts joined by a separator so assertions stay readable as single strings."""
    return join(TgFormat.split_for_telegram(html, limit), " || ")

def sample_lines() -> str:
    """Three sample lines built at runtime so a multi-parameter test block never needs a newline escape in an argument."""
    return concat("aaa", "\n", "bbb", "\n", "ccc")

def sample_join7() -> str:
    """Expected parts_preview output for sample_lines at limit 7."""
    return concat("aaa", "\n", "bbb", " || ", "ccc")

def sample_join2() -> str:
    """Expected parts_preview output for sample_lines at limit 2."""
    return concat("aaa", " || ", "bbb", " || ", "ccc")

def sample_pre() -> str:
    """A pre block followed by a short line, used to prove a pre block is never split."""
    return concat(TgFormat.pre_wrap(concat("a", "\n", "b")), "\nxx")

def sample_pre_join() -> str:
    """Expected parts_preview output for sample_pre at limit 5."""
    return concat(TgFormat.pre_wrap(concat("a", "\n", "b")), " || xx")
